interface Movable { Position getPosition(); void setPosition(Position p); }

class MoveServant {                                  // stateless servant
    void moveTo(Movable m, Position to) { m.setPosition(to); }
    void moveBy(Movable m, int dx, int dy) { moveTo(m, m.getPosition().shifted(dx, dy)); }
}
